ALTER TABLE "inscripcion_actividades" ADD FOREIGN KEY ("id_actividad") REFERENCES "actividades" ("id_actividad") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inscripcion_talleres" ADD FOREIGN KEY ("id_usuario") REFERENCES "usuarios" ("id_usuario") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inscripcion_talleres" ADD FOREIGN KEY ("id_taller") REFERENCES "talleres" ("id_taller") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

